Here is the commit message:
tcp: restrict SO_ATTACH_FILTER to priv users

This patch restricts the use of SO_ATTACH_FILTER (cBPF) on TCP sockets
to users with CAP_NET_ADMIN capability.

This blocks potential side-channel attack where an unprivileged application
attaches a filter to leak TCP sequence/acknowledgment numbers.

Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reported-by: Tamir Shahar <tamirthesis@gmail.com>
Reported-by: Amit Klein <aksecurity@gmail.com>
Cc: Willem de Bruijn <willemb@google.com>
Cc: Alexei Starovoitov <ast@kernel.org>
Cc: Daniel Borkmann <daniel@iogearbox.net>
Cc: Andrii Nakryiko <andrii@kernel.org>
Cc: Martin KaFai Lau <martin.lau@linux.dev>
Cc: Eduard Zingerman <eddyz87@gmail.com>
Cc: Kumar Kartikeya Dwivedi <memxor@gmail.com>
Cc: Song Liu <song@kernel.org>
Cc: Yonghong Song <yonghong.song@linux.dev>
Cc: Jiri Olsa <jolsa@kernel.org>
Cc: John Fastabend <john.fastabend@gmail.com>
Cc: Stanislav Fomichev <sdf@fomichev.me>
Acked-by: Daniel Borkmann <daniel@iogearbox.net>
Reviewed-by: Willem de Bruijn <willemb@google.com>
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
Lack of privilege check (CAP_NET_ADMIN) when attaching cBPF filter to TCP sockets via SO_ATTACH_FILTER, allowing unprivileged users to potentially leak TCP sequence/acknowledgment numbers.

Here is the patch:

 int sk_setsockopt(struct sock *sk, int level, int optname,
 		  sockptr_t optval, unsigned int optlen)
 {
 	struct so_timestamping timestamping;
 	struct socket *sock = sk->sk_socket;
 	struct sock_txtime sk_txtime;
 	int val;
 	int valbool;
 	struct linger ling;
 	int ret = 0;

 	/*
 	 *	Options without arguments
 	 */

 	if (optname == SO_BINDTODEVICE)
 		return sock_setbindtodevice(sk, optval, optlen);

 	if (optlen < sizeof(int))
 		return -EINVAL;

 	if (copy_from_sockptr(&val, optval, sizeof(val)))
 		return -EFAULT;

 	valbool = val ? 1 : 0;

 	/* handle options which do not require locking the socket. */
 	switch (optname) {
 	case SO_PRIORITY:
 		if (sk_set_prio_allowed(sk, val)) {
 			sock_set_priority(sk, val);
 			return 0;
 		}
 		return -EPERM;
 	case SO_TYPE:
 	case SO_PROTOCOL:
 	case SO_DOMAIN:
 	case SO_ERROR:
 		return -ENOPROTOOPT;
 #ifdef CONFIG_NET_RX_BUSY_POLL
 	case SO_BUSY_POLL:
 		if (val < 0)
 			return -EINVAL;
 		WRITE_ONCE(sk->sk_ll_usec, val);
 		return 0;
 	case SO_PREFER_BUSY_POLL:
 		if (valbool && !sockopt_capable(CAP_NET_ADMIN))
 			return -EPERM;
 		WRITE_ONCE(sk->sk_prefer_busy_poll, valbool);
 		return 0;
 	case SO_BUSY_POLL_BUDGET:
 		if (val > READ_ONCE(sk->sk_busy_poll_budget) &&
 		    !sockopt_capable(CAP_NET_ADMIN))
 			return -EPERM;
 		if (val < 0 || val > U16_MAX)
 			return -EINVAL;
 		WRITE_ONCE(sk->sk_busy_poll_budget, val);
 		return 0;
 #endif
 	case SO_MAX_PACING_RATE:
 		{
 		unsigned long ulval = (val == ~0U) ? ~0UL : (unsigned int)val;
 		unsigned long pacing_rate;

 		if (sizeof(ulval) != sizeof(val) &&
 		    optlen >= sizeof(ulval) &&
 		    copy_from_sockptr(&ulval, optval, sizeof(ulval))) {
 			return -EFAULT;
 		}
 		if (ulval != ~0UL)
 			cmpxchg(&sk->sk_pacing_status,
 				SK_PACING_NONE,
 				SK_PACING_NEEDED);
 		/* Pairs with READ_ONCE() from sk_getsockopt() */
 		WRITE_ONCE(sk->sk_max_pacing_rate, ulval);
 		pacing_rate = READ_ONCE(sk->sk_pacing_rate);
 		if (ulval < pacing_rate)
 			WRITE_ONCE(sk->sk_pacing_rate, ulval);
 		return 0;
 		}
 	case SO_TXREHASH:
 		if (!sk_is_tcp(sk))
 			return -EOPNOTSUPP;
 		if (val < -1 || val > 1)
 			return -EINVAL;
 		if ((u8)val == SOCK_TXREHASH_DEFAULT)
 			val = READ_ONCE(sock_net(sk)->core.sysctl_txrehash);
 		/* Paired with READ_ONCE() in tcp_rtx_synack()
 		 * and sk_getsockopt().
 		 */
 		WRITE_ONCE(sk->sk_txrehash, (u8)val);
 		return 0;
 	case SO_PEEK_OFF:
 		{
 		int (*set_peek_off)(struct sock *sk, int val);

 		set_peek_off = READ_ONCE(sock->ops)->set_peek_off;
 		if (set_peek_off)
 			ret = set_peek_off(sk, val);
 		else
 			ret = -EOPNOTSUPP;
 		return ret;
 		}
 #ifdef CONFIG_PAGE_POOL
 	case SO_DEVMEM_DONTNEED:
 		return sock_devmem_dontneed(sk, optval, optlen);
 #endif
 	case SO_SNDTIMEO_OLD:
 	case SO_SNDTIMEO_NEW:
 		return sock_set_timeout(&sk->sk_sndtimeo, optval,
 					optlen, optname == SO_SNDTIMEO_OLD);
 	case SO_RCVTIMEO_OLD:
 	case SO_RCVTIMEO_NEW:
 		return sock_set_timeout(&sk->sk_rcvtimeo, optval,
 					optlen, optname == SO_RCVTIMEO_OLD);
 	}

 	sockopt_lock_sock(sk);

 	switch (optname) {
 	case SO_DEBUG:
 		if (val && !sockopt_capable(CAP_NET_ADMIN))
 			ret = -EACCES;
 		else
 			sock_valbool_flag(sk, SOCK_DBG, valbool);
 		break;
 	case SO_REUSEADDR:
 		sk->sk_reuse = (valbool ? SK_CAN_REUSE : SK_NO_REUSE);
 		break;
 	case SO_REUSEPORT:
 		if (valbool && !sk_is_inet(sk))
 			ret = -EOPNOTSUPP;
 		else
 			sk->sk_reuseport = valbool;
 		break;
 	case SO_DONTROUTE:
 		sock_valbool_flag(sk, SOCK_LOCALROUTE, valbool);
 		sk_dst_reset(sk);
 		break;
 	case SO_BROADCAST:
 		sock_valbool_flag(sk, SOCK_BROADCAST, valbool);
 		break;
 	case SO_SNDBUF:
 		/* Don't error on this BSD doesn't and if you think
 		 * about it this is right. Otherwise apps have to
 		 * play 'guess the biggest size' games. RCVBUF/SNDBUF
 		 * are treated in BSD as hints
 		 */
 		val = min_t(u32, val, READ_ONCE(sysctl_wmem_max));
 set_sndbuf:
 		/* Ensure val * 2 fits into an int, to prevent max_t()
 		 * from treating it as a negative value.
 		 */
 		val = min_t(int, val, INT_MAX / 2);
 		sk->sk_userlocks |= SOCK_SNDBUF_LOCK;
 		WRITE_ONCE(sk->sk_sndbuf,
 			   max_t(int, val * 2, SOCK_MIN_SNDBUF));
 		/* Wake up sending tasks if we upped the value. */
 		sk->sk_write_space(sk);
 		break;

 	case SO_SNDBUFFORCE:
 		if (!sockopt_capable(CAP_NET_ADMIN)) {
 			ret = -EPERM;
 			break;
 		}

 		/* No negative values (to prevent underflow, as val will be
 		 * multiplied by 2).
 		 */
 		if (val < 0)
 			val = 0;
 		goto set_sndbuf;

 	case SO_RCVBUF:
 		/* Don't error on this BSD doesn't and if you think
 		 * about it this is right. Otherwise apps have to
 		 * play 'guess the biggest size' games. RCVBUF/SNDBUF
 		 * are treated in BSD as hints
 		 */
 		__sock_set_rcvbuf(sk, min_t(u32, val, READ_ONCE(sysctl_rmem_max)));
 		break;

 	case SO_RCVBUFFORCE:
 		if (!sockopt_capable(CAP_NET_ADMIN)) {
 			ret = -EPERM;
 			break;
 		}

 		/* No negative values (to prevent underflow, as val will be
 		 * multiplied by 2).
 		 */
 		__sock_set_rcvbuf(sk, max(val, 0));
 		break;

 	case SO_KEEPALIVE:
 		if (sk->sk_prot->keepalive)
 			sk->sk_prot->keepalive(sk, valbool);
 		sock_valbool_flag(sk, SOCK_KEEPOPEN, valbool);
 		break;

 	case SO_OOBINLINE:
 		sock_valbool_flag(sk, SOCK_URGINLINE, valbool);
 		break;

 	case SO_NO_CHECK:
 		sk->sk_no_check_tx = valbool;
 		break;

 	case SO_LINGER:
 		if (optlen < sizeof(ling)) {
 			ret = -EINVAL;	/* 1003.1g */
 			break;
 		}
 		if (copy_from_sockptr(&ling, optval, sizeof(ling))) {
 			ret = -EFAULT;
 			break;
 		}
 		if (!ling.l_onoff) {
 			sock_reset_flag(sk, SOCK_LINGER);
 		} else {
 			unsigned long t_sec = ling.l_linger;

 			if (t_sec >= MAX_SCHEDULE_TIMEOUT / HZ)
 				WRITE_ONCE(sk->sk_lingertime, MAX_SCHEDULE_TIMEOUT);
 			else
 				WRITE_ONCE(sk->sk_lingertime, t_sec * HZ);
 			sock_set_flag(sk, SOCK_LINGER);
 		}
 		break;

 	case SO_BSDCOMPAT:
 		break;

 	case SO_TIMESTAMP_OLD:
 	case SO_TIMESTAMP_NEW:
 	case SO_TIMESTAMPNS_OLD:
 	case SO_TIMESTAMPNS_NEW:
 		sock_set_timestamp(sk, optname, valbool);
 		break;

 	case SO_TIMESTAMPING_NEW:
 	case SO_TIMESTAMPING_OLD:
 		if (optlen == sizeof(timestamping)) {
 			if (copy_from_sockptr(&timestamping, optval,
 					      sizeof(timestamping))) {
 				ret = -EFAULT;
 				break;
 			}
 		} else {
 			memset(&timestamping, 0, sizeof(timestamping));
 			timestamping.flags = val;
 		}
 		ret = sock_set_timestamping(sk, optname, timestamping);
 		break;

 	case SO_RCVLOWAT:
 		{
 		int (*set_rcvlowat)(struct sock *sk, int val) = NULL;

 		if (val < 0)
 			val = INT_MAX;
 		if (sock)
 			set_rcvlowat = READ_ONCE(sock->ops)->set_rcvlowat;
 		if (set_rcvlowat)
 			ret = set_rcvlowat(sk, val);
 		else
 			WRITE_ONCE(sk->sk_rcvlowat, val ? : 1);
 		break;
 		}
 	case SO_ATTACH_FILTER: {
 		struct sock_fprog fprog;

+		if (sk_is_tcp(sk) &&
+		    !sockopt_ns_capable(sock_net(sk)->user_ns, CAP_NET_ADMIN)) {
+			ret = -EPERM;
+			break;
+		}
 		ret = copy_bpf_fprog_from_user(&fprog, optval, optlen);
 		if (!ret)
 			ret = sk_attach_filter(&fprog, sk);
 		break;
 	}
 	case SO_ATTACH_BPF:
 		ret = -EINVAL;
 		if (optlen == sizeof(u32)) {
 			u32 ufd;

 			ret = -EFAULT;
 			if (copy_from_sockptr(&ufd, optval, sizeof(ufd)))
 				break;

 			ret = sk_attach_bpf(ufd, sk);
 		}
 		break;

 	case SO_ATTACH_REUSEPORT_CBPF: {
 		struct sock_fprog fprog;

 		ret = copy_bpf_fprog_from_user(&fprog, optval, optlen);
 		if (!ret)
 			ret = sk_reuseport_attach_filter(&fprog, sk);
 		break;
 	}
 	case SO_ATTACH_REUSEPORT_EBPF:
 		ret = -EINVAL;
 		if (optlen == sizeof(u32)) {
 			u32 ufd;

 			ret = -EFAULT;
 			if (copy_from_sockptr(&ufd, optval, sizeof(ufd)))
 				break;

 			ret = sk_reuseport_attach_bpf(ufd, sk);
 		}
 		break;

 	case SO_DETACH_REUSEPORT_BPF:
 		ret = reuseport_detach_prog(sk);
 		break;

 	case SO_DETACH_FILTER:
 		ret = sk_detach_filter(sk);
 		break;

 	case SO_LOCK_FILTER:
 		if (sock_flag(sk, SOCK_FILTER_LOCKED) && !valbool)
 			ret = -EPERM;
 		else
 			sock_valbool_flag(sk, SOCK_FILTER_LOCKED, valbool);
 		break;

 	case SO_MARK:
 		if (!sockopt_ns_capable(sock_net(sk)->user_ns, CAP_NET_RAW) &&
 		    !sockopt_ns_capable(sock_net(sk)->user_ns, CAP_NET_ADMIN)) {
 			ret = -EPERM;
 			break;
 		}

 		__sock_set_mark(sk, val);
 		break;
 	case SO_RCVMARK:
 		sock_valbool_flag(sk, SOCK_RCVMARK, valbool);
 		break;

 	case SO_RCVPRIORITY:
 		sock_valbool_flag(sk, SOCK_RCVPRIORITY, valbool);
 		break;

 	case SO_RXQ_OVFL:
 		sock_valbool_flag(sk, SOCK_RXQ_OVFL, valbool);
 		break;

 	case SO_WIFI_STATUS:
 		sock_valbool_flag(sk, SOCK_WIFI_STATUS, valbool);
 		break;

 	case SO_NOFCS:
 		sock_valbool_flag(sk, SOCK_NOFCS, valbool);
 		break;

 	case SO_SELECT_ERR_QUEUE:
 		sock_valbool_flag(sk, SOCK_SELECT_ERR_QUEUE, valbool);
 		break;

 	case SO_PASSCRED:
 		if (sk_may_scm_recv(sk))
 			sk->sk_scm_credentials = valbool;
 		else
 			ret = -EOPNOTSUPP;
 		break;

 	case SO_PASSSEC:
 		if (IS_ENABLED(CONFIG_SECURITY_NETWORK) && sk_may_scm_recv(sk))
 			sk->sk_scm_security = valbool;
 		else
 			ret = -EOPNOTSUPP;
 		break;

 	case SO_PASSPIDFD:
 		if (sk_is_unix(sk))
 			sk->sk_scm_pidfd = valbool;
 		else
 			ret = -EOPNOTSUPP;
 		break;

 	case SO_PASSRIGHTS:
 		if (sk_is_unix(sk))
 			sk->sk_scm_rights = valbool;
 		else
 			ret = -EOPNOTSUPP;
 		break;

 	case SO_INCOMING_CPU:
 		reuseport_update_incoming_cpu(sk, val);
 		break;

 	case SO_CNX_ADVICE:
 		if (val == 1)
 			dst_negative_advice(sk);
 		break;

 	case SO_ZEROCOPY:
 		if (sk->sk_family == PF_INET || sk->sk_family == PF_INET6) {
 			if (!(sk_is_tcp(sk) ||
 			      (sk->sk_type == SOCK_DGRAM &&
 			       sk->sk_protocol == IPPROTO_UDP)))
 				ret = -EOPNOTSUPP;
 		} else if (sk->sk_family != PF_RDS) {
 			ret = -EOPNOTSUPP;
 		}
 		if (!ret) {
 			if (val < 0 || val > 1)
 				ret = -EINVAL;
 			else
 				sock_valbool_flag(sk, SOCK_ZEROCOPY, valbool);
 		}
 		break;

 	case SO_TXTIME:
 		if (optlen != sizeof(struct sock_txtime)) {
 			ret = -EINVAL;
 			break;
 		} else if (copy_from_sockptr(&sk_txtime, optval,
 			   sizeof(struct sock_txtime))) {
 			ret = -EFAULT;
 			break;
 		} else if (sk_txtime.flags & ~SOF_TXTIME_FLAGS_MASK) {
 			ret = -EINVAL;
 			break;
 		}
 		/* CLOCK_MONOTONIC is only used by sch_fq, and this packet
 		 * scheduler has enough safe guards.
 		 */
 		if (sk_txtime.clockid != CLOCK_MONOTONIC &&
 		    !sockopt_ns_capable(sock_net(sk)->user_ns, CAP_NET_ADMIN)) {
 			ret = -EPERM;
 			break;
 		}

 		ret = sockopt_validate_clockid(sk_txtime.clockid);
 		if (ret)
 			break;

 		sock_valbool_flag(sk, SOCK_TXTIME, true);
 		sk->sk_clockid = sk_txtime.clockid;
 		sk->sk_txtime_deadline_mode =
 			!!(sk_txtime.flags & SOF_TXTIME_DEADLINE_MODE);
 		sk->sk_txtime_report_errors =
 			!!(sk_txtime.flags & SOF_TXTIME_REPORT_ERRORS);
 		break;

 	case SO_BINDTOIFINDEX:
 		ret = sock_bindtoindex_locked(sk, val);
 		break;

 	case SO_BUF_LOCK:
 		if (val & ~SOCK_BUF_LOCK_MASK) {
 			ret = -EINVAL;
 			break;
 		}
 		sk->sk_userlocks = val | (sk->sk_userlocks &
 					  ~SOCK_BUF_LOCK_MASK);
 		break;

 	case SO_RESERVE_MEM:
 	{
 		int delta;

 		if (val < 0) {
 			ret = -EINVAL;
 			break;
 		}

 		delta = val - sk->sk_reserved_mem;
 		if (delta < 0)
 			sock_release_reserved_memory(sk, -delta);
 		else
 			ret = sock_reserve_memory(sk, delta);
 		break;
 	}

 	default:
 		ret = -ENOPROTOOPT;
 		break;
 	}
 	sockopt_release_sock(sk);
 	return ret;
 }



